DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'redgate'
      AND table_name   = 'feedback_audit_summary'
      AND column_name  = 'customer_id'
  ) THEN
    EXECUTE 'ALTER VIEW redgate.feedback_audit_summary RENAME COLUMN customer_id TO cust_id';
  END IF;
END
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION redgate.count_recent_audits(p_days integer)
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE v_count integer;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM redgate.feedback_audit a
  WHERE a.created_at > now() - (p_days || ' days')::interval;
  RETURN v_count;
END$$;
